  "decline_reason": "",
  "claims": [
    {
      "text": "Yes, in principle: the Manual permits an international application based on an existing application or registration in a Madrid Protocol Contracting Party, with the same owner(s), an identical mark and only some of the basic mark’s goods or services.",
      "quotes": [
        {
          "ref": "TMM/Part60/1/1/7",
          "quote": "An international application must be based on an existing application(s) or registration(s) (basic trade mark) in a Contracting Party to the Madrid Protocol. The international application must have the same owner(s) as the basic trade mark, the identical trade mark as the basic trade mark(s) and cover the same, or some only of the goods and/or services as the basic trade mark(s)."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual also requires the international application to contain any indications in the basic mark, such as a claim to colour as a distinctive feature.",
      "quotes": [
        {
          "ref": "TMM/Part60/1/1/7",
          "quote": "It must also contain any indications, such as a claim to colour as a distinctive feature of the mark, that are contained in the basic trade mark(s)."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For filing in Australia, the Manual states that the owner must be an Australian national, be domiciled in Australia, or have a real and effective industrial or commercial establishment in Australia.",
      "quotes": [
        {
          "ref": "TMM/Part60/1/1/1",
          "quote": "The owner of an existing national trade mark may only file an international application in Australia if they are an Australian national, are domiciled in Australia, or have a real and effective industrial or commercial establishment in Australia."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "These are requirements for the international application, not an assurance of protection: the Manual states that each designated Contracting Party examines the international registration under its own trade mark legislation.",
      "quotes": [
        {
          "ref": "TMM/Part60/1/1/5",
          "quote": "Each designated Contracting Party examines the international registration in accordance with its own trade mark legislation."
        }
      ],
      "authority": "manual"
    }
  ],
  "declined": false,
